#!/usr/bin/env python3
"""Statically extract recurrence vectors from dateutil tests/test_rrule.py
using the `ast` module only (the test file is never imported or executed).

Usage: python3 -I conv_dateutil.py TEST_RRULE_PY OUT.json COMMIT SKIPREPORT.json
"""
import ast
import json
import os
import re
import sys
from collections import Counter, OrderedDict

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import vec_common as vc  # noqa: E402

try:
    from zoneinfo import ZoneInfo  # stdlib; used only to convert aware UNTIL values to UTC
except Exception:  # noqa: BLE001
    ZoneInfo = None

FREQS = {"YEARLY", "MONTHLY", "WEEKLY", "DAILY", "HOURLY", "MINUTELY", "SECONDLY"}
WDAYS = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"]
ORDER = ["freq", "interval", "count", "until", "wkst", "bysetpos", "bymonth",
         "bymonthday", "byyearday", "byweekno", "byweekday", "byhour",
         "byminute", "bysecond", "byeaster"]
NAMES = {"freq": "FREQ", "interval": "INTERVAL", "count": "COUNT", "until": "UNTIL",
         "wkst": "WKST", "bysetpos": "BYSETPOS", "bymonth": "BYMONTH",
         "bymonthday": "BYMONTHDAY", "byyearday": "BYYEARDAY", "byweekno": "BYWEEKNO",
         "byweekday": "BYDAY", "byhour": "BYHOUR", "byminute": "BYMINUTE",
         "bysecond": "BYSECOND", "byeaster": "BYEASTER"}

SEM = (
    "dateutil tests/test_rrule.py, extracted statically with Python's ast module (never executed). "
    "Python API cases rrule(FREQ, dtstart=..., **kwargs) were mapped to RRULE text (freq->FREQ, interval, count, "
    "until (naive datetime -> floating YYYYMMDDTHHMMSS; date -> YYYYMMDD; UTC-aware -> ...Z), wkst, bysetpos, "
    "bymonth, bymonthday, byyearday, byweekno, byweekday (MO..SU; MO(+1)/TU(-1) -> 1MO/-1TU; ints 0..6 = MO..SU), "
    "byhour, byminute, bysecond, byeaster -> BYEASTER=n with extensions [\"BYEASTER\"]); rrulestr(...) cases keep the "
    "source's RRULE/EXRULE text verbatim (minus the 'RRULE:' prefix) and its DTSTART/RDATE/EXDATE values; rruleset() "
    "cases map .rrule/.exrule/.rdate/.exdate calls (all member rules must share one dtstart). "
    "dateutil only yields instances generated by the rules (plus RDATEs): DTSTART is NOT added unless it matches "
    "the rule, and COUNT does not count a non-matching DTSTART, so include_dtstart=false - except rrulestr(..., "
    "compatible=True), which adds DTSTART as an RDATE (include_dtstart=true). "
    "dateutil fills unspecified BYxxx parts from DTSTART exactly like RFC 5545. "
    "Unlike RFC 5545 it accepts rule-part combinations that RFC 5545 forbids (e.g. BYWEEKNO/BYYEARDAY with "
    "MONTHLY/WEEKLY/DAILY..., BYMONTHDAY with WEEKLY, BYDAY ordinals with non-MONTHLY/YEARLY freq, where the ordinal "
    "is ignored); those cases carry NONSTANDARD:* markers in 'extensions'. "
    "Naive datetimes are floating; tzinfo=tz.gettz(NAME) gives 'tzid' (wall-clock values); tz.UTC gives Z. "
    "dtstart=date(...) is promoted by dateutil to midnight, so dtstart is written as YYYYMMDDT000000. "
    "between: rule.between(after, before, inc) - exclusive unless inc=True; after(dt, inc) -> between.start with "
    "limit 1; xafter(dt, count=N, inc) -> between.start with limit N; a slice rule[:N] -> limit N. "
    "error=true: the source expects ValueError (assertRaises/pytest.raises) at construction or iteration; some "
    "of these are dateutil-specific (e.g. rules whose BYxxx can never match with the given INTERVAL).")


class Skip(Exception):
    pass


def const(node, env):
    """Resolve a literal/simple expression to a Python value or tagged tuple."""
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.USub, ast.UAdd)):
        v = const(node.operand, env)
        if not isinstance(v, int):
            raise Skip("non-int unary operand")
        return -v if isinstance(node.op, ast.USub) else v
    if isinstance(node, (ast.Tuple, ast.List)):
        return [const(e, env) for e in node.elts]
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        a, b = const(node.left, env), const(node.right, env)
        if isinstance(a, str) and isinstance(b, str):
            return a + b
        raise Skip("non-string concatenation")
    if isinstance(node, ast.Name):
        if node.id in FREQS:
            return ("freq", node.id)
        if node.id in WDAYS:
            return ("wd", node.id, None)
        if node.id in ("True", "False", "None"):
            return {"True": True, "False": False, "None": None}[node.id]
        if node.id in env:
            return const(env[node.id], env)
        raise Skip("unresolved name %s" % node.id)
    if isinstance(node, ast.Call):
        fn = node.func
        if isinstance(fn, ast.Name) and fn.id in WDAYS:
            if len(node.args) != 1 or node.keywords:
                raise Skip("weekday call shape")
            return ("wd", fn.id, const(node.args[0], env))
        if isinstance(fn, ast.Name) and fn.id in ("datetime", "date"):
            return dt_value(node, env)
        if isinstance(fn, ast.Attribute) and isinstance(fn.value, ast.Name) and fn.value.id == "tz":
            if fn.attr == "gettz" and len(node.args) == 1 and isinstance(node.args[0], ast.Constant):
                return ("tz", node.args[0].value)
            if fn.attr == "tzutc" and not node.args:
                return ("tz", "UTC")
            raise Skip("unsupported tz constructor tz.%s" % fn.attr)
        if isinstance(fn, ast.Attribute) and fn.attr == "join" and isinstance(fn.value, ast.Constant) \
                and isinstance(fn.value.value, str) and len(node.args) == 1:
            parts = const(node.args[0], env)
            if not all(isinstance(p, str) for p in parts):
                raise Skip("join of non-strings")
            return fn.value.value.join(parts)
        if isinstance(fn, ast.Name) and fn.id == "long":
            raise Skip("python2 long()")
        raise Skip("unsupported call %s" % ast.unparse(fn))
    if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name) and node.value.id == "tz" and node.attr == "UTC":
        return ("tz", "UTC")
    raise Skip("unsupported expression %s" % type(node).__name__)


def dt_value(call, env):
    kind = call.func.id
    args = [const(a, env) for a in call.args]
    kw = {k.arg: k.value for k in call.keywords}
    if not all(isinstance(a, int) for a in args):
        raise Skip("non-int datetime args")
    tzv = None
    if "tzinfo" in kw:
        tzv = const(kw.pop("tzinfo"), env)
        if not (isinstance(tzv, tuple) and tzv[0] == "tz"):
            raise Skip("unsupported tzinfo")
        tzv = tzv[1]
    if kw:
        raise Skip("unsupported datetime keywords %s" % sorted(kw))
    if kind == "date":
        if len(args) != 3:
            raise Skip("date arity")
        return ("date", tuple(args), None)
    if len(args) < 3 or len(args) > 7:
        raise Skip("datetime arity")
    if len(args) == 7 and args[6] != 0:
        raise Skip("microseconds")
    a = (args + [0, 0, 0])[:6]
    return ("dt", tuple(a), tzv)


def fmt_dt(v, zone):
    """Format a ('dt'|'date', tuple, tz) value relative to the case zone.
    zone: None (floating), 'UTC', or IANA name."""
    kind, t, tzv = v
    if kind == "date":
        return "%04d%02d%02d" % t
    if tzv != zone:
        raise Skip("mixed time zones (%s vs %s)" % (tzv, zone))
    return vc.basic(*t, utc=(zone == "UTC"))


def zone_of(v):
    return v[2] if v[0] == "dt" else None


def wd_text(v):
    if isinstance(v, int) and not isinstance(v, bool):
        if not 0 <= v <= 6:
            raise Skip("weekday int out of range")
        return WDAYS[v]
    if isinstance(v, tuple) and v[0] == "wd":
        n = v[2]
        if n is None:
            return v[1]
        if not isinstance(n, int):
            raise Skip("weekday n")
        return "%d%s" % (n, v[1])
    raise Skip("bad weekday value")


def list_of(v):
    return v if isinstance(v, list) else [v]


def rrule_from_call(call, env, extra_kw=None):
    """rrule(FREQ, dtstart=..., ...) -> (dtstart_value, rule_text, extensions, comments)"""
    kw = OrderedDict()
    if call.args:
        if len(call.args) != 1:
            raise Skip("positional args beyond freq")
        kw["freq"] = const(call.args[0], env)
    for k in call.keywords:
        if k.arg is None:
            # **dict(...)
            if isinstance(k.value, ast.Call) and isinstance(k.value.func, ast.Name) and k.value.func.id == "dict":
                for kk in k.value.keywords:
                    kw[kk.arg] = const(kk.value, env)
                continue
            raise Skip("**kwargs")
        kw[k.arg] = const(k.value, env)
    if extra_kw:
        kw.update(extra_kw)
    return rrule_from_kwargs(kw)


def rrule_from_kwargs(kw):
    kw = dict(kw)
    kw.pop("cache", None)
    comments = []
    ext = []
    if "dtstart" not in kw:
        raise Skip("no dtstart (dateutil uses datetime.now())")
    dts = kw.pop("dtstart")
    if not (isinstance(dts, tuple) and dts[0] in ("dt", "date")):
        raise Skip("bad dtstart")
    if dts[0] == "date":
        comments.append("dtstart=date(...) in source; dateutil promotes it to a midnight datetime")
        dts = ("dt", tuple(list(dts[1]) + [0, 0, 0]), None)
    zone = dts[2]
    freq = kw.get("freq")
    if not (isinstance(freq, tuple) and freq[0] == "freq"):
        raise Skip("freq not a constant")
    unknown = set(kw) - set(ORDER)
    if unknown:
        raise Skip("unsupported rrule kwargs %s" % sorted(unknown))
    parts = []
    for k in ORDER:
        if k not in kw or kw[k] is None:
            continue
        v = kw[k]
        if k == "freq":
            parts.append("FREQ=" + v[1])
        elif k in ("interval", "count"):
            if not isinstance(v, int):
                raise Skip("%s not int" % k)
            parts.append("%s=%d" % (NAMES[k], v))
        elif k == "until":
            if not (isinstance(v, tuple) and v[0] in ("dt", "date")):
                raise Skip("until value")
            if v[0] == "date":
                parts.append("UNTIL=%04d%02d%02d" % v[1])
                comments.append("until=date(...) in source (DATE UNTIL with DATE-TIME DTSTART); dateutil treats it as midnight")
            elif v[2] is None:
                if zone is not None:
                    raise Skip("naive until with aware dtstart")
                parts.append("UNTIL=" + vc.basic(*v[1]))
            elif v[2] == "UTC":
                parts.append("UNTIL=" + vc.basic(*v[1], utc=True))
            else:
                if ZoneInfo is None:
                    raise Skip("cannot convert aware until")
                import datetime as _d
                u = _d.datetime(*v[1], tzinfo=ZoneInfo(v[2])).astimezone(_d.timezone.utc)
                parts.append("UNTIL=" + vc.basic(u.year, u.month, u.day, u.hour, u.minute, u.second, utc=True))
                comments.append("until given in source as %s wall-clock %s; converted to UTC" % (v[2], vc.basic(*v[1])))
        elif k == "wkst":
            parts.append("WKST=" + wd_text(v))
        elif k == "byweekday":
            parts.append("BYDAY=" + ",".join(wd_text(x) for x in list_of(v)))
        else:
            vals = list_of(v)
            if not all(isinstance(x, int) and not isinstance(x, bool) for x in vals):
                raise Skip("%s values not ints" % k)
            parts.append("%s=%s" % (NAMES[k], ",".join(str(x) for x in vals)))
            if k == "byeaster":
                ext.append("BYEASTER")
    return dts, ";".join(parts), ext, comments


DTPROP = re.compile(r"^(\d{8})(T\d{6}Z?)?$")


def parse_val(text, params):
    """DTSTART/EXDATE/RDATE value(s) from rrulestr text -> (list of basic strings, tzid)"""
    tzid = None
    for p in params:
        pu = p.upper()
        if pu.startswith("TZID="):
            tzid = p.split("=", 1)[1]
        elif pu in ("VALUE=DATE", "VALUE=DATE-TIME"):
            pass
        else:
            raise Skip("unsupported parameter %s" % p)
    out = []
    for v in text.split(","):
        v = v.strip()
        if not DTPROP.match(v.upper()):
            raise Skip("unrepresentable date value %r" % v)
        out.append(v.upper())
    return out, tzid


def rrulestr_case(call, env):
    """rrulestr("...", **kw) -> dict(dtstart, tzid, rrule, exrule, rdate, exdate, include_dtstart, comments, ext)"""
    if len(call.args) != 1:
        raise Skip("rrulestr arity")
    s = const(call.args[0], env)
    if not isinstance(s, str):
        raise Skip("rrulestr arg not a string")
    kw = {}
    for k in call.keywords:
        if k.arg is None:
            raise Skip("rrulestr **kwargs")
        kw[k.arg] = k.value
    allowed = {"dtstart", "cache", "forceset", "compatible", "unfold"}
    if set(kw) - allowed:
        raise Skip("unsupported rrulestr kwargs %s" % sorted(set(kw) - allowed))
    flags = {k: const(kw[k], env) for k in ("forceset", "compatible", "unfold", "cache") if k in kw}
    compatible = bool(flags.get("compatible"))
    unfold = bool(flags.get("unfold")) or compatible
    comments = []
    dtstart = None
    tzid = None
    if "dtstart" in kw:
        d = const(kw["dtstart"], env)
        if not (isinstance(d, tuple) and d[0] in ("dt", "date")):
            raise Skip("rrulestr dtstart kwarg")
        if d[0] == "date":
            d = ("dt", tuple(list(d[1]) + [0, 0, 0]), None)
        tzid = d[2]
        dtstart = vc.basic(*d[1], utc=(tzid == "UTC"))
        if tzid == "UTC":
            tzid = None
        comments.append("DTSTART supplied as rrulestr(dtstart=...) keyword")
    if not s.strip():
        raise Skip("empty rrulestr string")
    if unfold:
        lines = s.splitlines()
        i = 0
        while i < len(lines):
            line = lines[i].rstrip()
            if not line:
                del lines[i]
            elif i > 0 and line[0] == " ":
                lines[i - 1] += line[1:]
                del lines[i]
            else:
                lines[i] = line
                i += 1
        if "\n " in s:
            comments.append("source string uses line folding (unfold=True); RRULE text here is unfolded")
    else:
        lines = s.split()
    rr, exr, rd, exd = [], [], [], []
    rd_tz, exd_tz = [], []
    for line in lines:
        if not line:
            continue
        if ":" not in line:
            name, value = "RRULE", line
            params = []
        else:
            name, value = line.split(":", 1)
            params = name.split(";")[1:]
            name = name.split(";")[0]
        nu = name.upper()
        if nu == "RRULE":
            if params:
                raise Skip("RRULE params")
            rr.append(value)
        elif nu == "EXRULE":
            exr.append(value)
        elif nu == "RDATE":
            vals, tz_ = parse_val(value, params)
            rd.extend(vals)
            rd_tz.append(tz_)
        elif nu == "EXDATE":
            vals, tz_ = parse_val(value, params)
            exd.extend(vals)
            exd_tz.append(tz_)
        elif nu == "DTSTART":
            vals, tz_ = parse_val(value, params)
            if len(vals) != 1:
                raise Skip("multiple DTSTART values")
            dtstart = vals[0]
            tzid = tz_
        else:
            raise Skip("unsupported property %s" % name)
    if not rr and not rd:
        raise Skip("no RRULE")
    if not rr:
        comments.append("no RRULE: recurrence set = RDATEs minus EXDATE/EXRULE")
    if dtstart is None:
        raise Skip("no DTSTART")
    for t in rd_tz + exd_tz:
        if t is not None and t != tzid:
            raise Skip("EXDATE/RDATE zone differs from DTSTART zone")
    if tzid and dtstart.endswith("Z"):
        comments.append("DTSTART carries both TZID=%s and a UTC 'Z' suffix (RFC 5545 3.3.5 forbids TZID on UTC times)" % tzid)
    if compatible:
        comments.append("rrulestr(compatible=True): dateutil adds DTSTART to the set as an RDATE (RFC 5545 semantics)")
    ext = []
    return dict(dtstart=dtstart, tzid=tzid, rrule=rr, exrule=exr, rdate=rd, exdate=exd,
                include_dtstart=compatible, comments=comments, ext=ext)


def build_source(node, env, sets):
    """Return a case skeleton for an expression producing a recurrence."""
    if isinstance(node, ast.Name):
        if node.id in sets:
            return set_case(sets[node.id])
        if node.id in env:
            return build_source(env[node.id], env, sets)
        raise Skip("unresolved recurrence name %s" % node.id)
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        if node.func.id == "rrule":
            dts, text, ext, cm = rrule_from_call(node, env)
            zone = dts[2]
            return dict(dtstart=vc.basic(*dts[1], utc=(zone == "UTC")), tzid=None if zone in (None, "UTC") else zone,
                        zone=zone, rrule=[text], exrule=[], rdate=[], exdate=[], include_dtstart=False,
                        comments=cm, ext=ext)
        if node.func.id == "rrulestr":
            c = rrulestr_case(node, env)
            c["zone"] = c["tzid"] if c["tzid"] else ("UTC" if c["dtstart"].endswith("Z") else None)
            return c
        if node.func.id == "list" and len(node.args) == 1:
            return build_source(node.args[0], env, sets)
    raise Skip("unsupported recurrence expression %s" % ast.unparse(node)[:60])


def set_case(ops):
    rr, exr, rd, exd = [], [], [], []
    dts = None
    cm = []
    ext = []
    for op, val in ops:
        if op in ("rrule", "exrule"):
            d, text, e, c = val
            if dts is None:
                dts = d
            elif d != dts:
                raise Skip("rruleset members have different dtstart")
            (rr if op == "rrule" else exr).append(text)
            ext += e
            cm += c
        else:
            (rd if op == "rdate" else exd).append(val)
    if dts is None:
        raise Skip("rruleset without rrule (no DTSTART to anchor)")
    zone = dts[2]
    return dict(dtstart=vc.basic(*dts[1], utc=(zone == "UTC")), tzid=None if zone in (None, "UTC") else zone,
                zone=zone, rrule=rr, exrule=exr,
                rdate=[fmt_dt(v, zone) for v in rd], exdate=[fmt_dt(v, zone) for v in exd],
                include_dtstart=False, comments=cm, ext=ext)


def expected_list(node, env, zone):
    v = const(node, env)
    if isinstance(v, tuple):
        v = [v]
    if not isinstance(v, list):
        raise Skip("expected is not a list of datetimes")
    out = []
    for x in v:
        if not (isinstance(x, tuple) and x[0] in ("dt", "date")):
            raise Skip("expected element not a datetime")
        if x[0] == "dt" and zone not in (None, "UTC") and x[2] != zone:
            raise Skip("expected zone mismatch")
        out.append(fmt_dt(x, zone))
    return out


def zone_fix(c):
    """normalise zone for rrulestr cases where dtstart text carries Z"""
    return c.get("zone")


class Extractor:
    def __init__(self):
        self.cases = []
        self.skips = Counter()
        self.func_status = []

    def run(self, tree):
        for top in tree.body:
            if isinstance(top, ast.ClassDef):
                for f in top.body:
                    if isinstance(f, ast.FunctionDef) and f.name.startswith("test"):
                        self.func(f, top.name)
            elif isinstance(top, ast.FunctionDef) and top.name.startswith("test"):
                self.func(top, None)

    def func(self, f, cls):
        qual = "%s.%s" % (cls, f.name) if cls else f.name
        env = {}
        sets = {}
        got = []
        reasons = []
        decos = [ast.unparse(d) for d in f.decorator_list]
        xfail = any("xfail" in d for d in decos)

        def emit(case_skel, expected, between=None, limit=None, error=False, extra_comment=None, line=None):
            got.append(dict(skel=case_skel, expected=expected, between=between, limit=limit,
                            error=error, extra=extra_comment, line=line))

        def handle_assert(actual, exp_node, line):
            # unwrap list(...) and slices
            limit = None
            between = None
            node = actual
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "list" and len(node.args) == 1:
                node = node.args[0]
            if isinstance(node, ast.Subscript):
                sl = node.slice
                if isinstance(sl, ast.Slice) and sl.step is None and (sl.lower is None or (isinstance(sl.lower, ast.Constant) and sl.lower.value == 0)):
                    if sl.upper is not None:
                        if not isinstance(sl.upper, ast.Constant):
                            raise Skip("slice bound")
                        limit = sl.upper.value
                    node = node.value
                else:
                    raise Skip("__getitem__ index/slice API")
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
                meth = node.func.attr
                if meth in ("between", "after", "xafter"):
                    src = build_source(node.func.value, env, sets)
                    zone = src["zone"]
                    kw = {k.arg: const(k.value, env) for k in node.keywords}
                    a = [const(x, env) for x in node.args]
                    inc = bool(kw.pop("inc", False))
                    if meth == "between":
                        if len(a) == 3:
                            inc = bool(a.pop())
                        if len(a) != 2 or kw:
                            raise Skip("between args")
                        between = {"start": fmt_dt(a[0], zone), "end": fmt_dt(a[1], zone), "inclusive": inc}
                    elif meth == "after":
                        if len(a) == 2:
                            inc = bool(a.pop())
                        if len(a) != 1 or kw:
                            raise Skip("after args")
                        between = {"start": fmt_dt(a[0], zone), "inclusive": inc}
                        limit = 1
                    else:
                        cnt = kw.pop("count", None)
                        if len(a) != 1 or kw or not isinstance(cnt, int):
                            raise Skip("xafter args")
                        between = {"start": fmt_dt(a[0], zone), "inclusive": inc}
                        limit = cnt
                    exp = expected_list(exp_node, env, zone)
                    emit(src, exp, between=between, limit=limit, line=line,
                         extra_comment="%s()" % meth)
                    return
                raise Skip("other API .%s()" % meth)
            if isinstance(node, (ast.Compare, ast.Attribute)) or (isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id in ("isinstance", "str", "repr", "len")):
                raise Skip("non-instance-list assertion (str/repr/type/contains/count)")
            src = build_source(node, env, sets)
            exp = expected_list(exp_node, env, src["zone"])
            emit(src, exp, limit=limit, line=line)

        def error_from(node, line):
            """Find rrule/rrulestr calls under node and emit error cases."""
            found = False
            for sub in ast.walk(node):
                if isinstance(sub, ast.Call) and isinstance(sub.func, ast.Name) and sub.func.id in ("rrule", "rrulestr"):
                    src = build_source(sub, env, sets)
                    emit(src, [], error=True, line=line)
                    found = True
            if not found:
                raise Skip("assertRaises without rrule/rrulestr call")

        def walk(stmts):
            for st in stmts:
                line = getattr(st, "lineno", None)
                try:
                    if isinstance(st, ast.Assign) and len(st.targets) == 1 and isinstance(st.targets[0], ast.Name):
                        name = st.targets[0].id
                        v = st.value
                        if isinstance(v, ast.Call) and isinstance(v.func, ast.Name) and v.func.id == "rruleset":
                            sets[name] = []
                        else:
                            env[name] = v
                            sets.pop(name, None)
                        continue
                    if isinstance(st, ast.FunctionDef):
                        env[st.name] = st
                        continue
                    if isinstance(st, ast.Expr) and isinstance(st.value, ast.Call):
                        c = st.value
                        fn = c.func
                        if isinstance(fn, ast.Attribute) and isinstance(fn.value, ast.Name) and fn.value.id in sets \
                                and fn.attr in ("rrule", "exrule", "rdate", "exdate"):
                            arg = c.args[0]
                            if fn.attr in ("rrule", "exrule"):
                                if not (isinstance(arg, ast.Call) and isinstance(arg.func, ast.Name) and arg.func.id == "rrule"):
                                    raise Skip("rruleset.%s with non-rrule argument" % fn.attr)
                                sets[fn.value.id].append((fn.attr, rrule_from_call(arg, env)))
                            else:
                                sets[fn.value.id].append((fn.attr, const(arg, env)))
                            continue
                        if isinstance(fn, ast.Attribute) and isinstance(fn.value, ast.Name) and fn.value.id == "self":
                            if fn.attr == "assertEqual" and len(c.args) == 2:
                                handle_assert(c.args[0], c.args[1], line)
                                continue
                            if fn.attr == "assertRaises":
                                if len(c.args) >= 2:
                                    target = c.args[1]
                                    if isinstance(target, ast.Name) and target.id in ("rrule", "rrulestr"):
                                        fake = ast.Call(func=ast.Name(id=target.id, ctx=ast.Load()), args=c.args[2:], keywords=c.keywords)
                                        error_from(fake, line)
                                        continue
                                    if isinstance(target, ast.Name) and isinstance(env.get(target.id), ast.FunctionDef):
                                        error_from(env[target.id], line)
                                        continue
                                raise Skip("assertRaises shape")
                            if fn.attr == "_rrulestr_reverse_test":
                                raise Skip("str() round-trip test (no expected instances)")
                            raise Skip("other assertion self.%s" % fn.attr)
                        raise Skip("other call statement %s" % ast.unparse(fn)[:40])
                    if isinstance(st, ast.Assert):
                        t = st.test
                        if isinstance(t, ast.Compare) and len(t.ops) == 1 and isinstance(t.ops[0], ast.Eq):
                            handle_assert(t.left, t.comparators[0], line)
                            continue
                        raise Skip("assert of non-equality")
                    if isinstance(st, ast.With):
                        ctx = ast.unparse(st.items[0].context_expr)
                        if "assertRaises(ValueError)" in ctx or "pytest.raises(ValueError)" in ctx:
                            error_from(ast.Module(body=st.body, type_ignores=[]), line)
                            continue
                        if "warns" in ctx:
                            raise Skip("pytest.warns (warning only, instances not asserted)")
                        raise Skip("with-block %s" % ctx[:40])
                    if isinstance(st, ast.If):
                        raise Skip("conditional block (python2-only)")
                    if isinstance(st, ast.For):
                        if all(isinstance(b, ast.Pass) for b in st.body):
                            continue  # cache warm-up loop
                        raise Skip("for-loop (parametrised via loop)")
                    if isinstance(st, (ast.Pass, ast.ClassDef)):
                        continue
                    if isinstance(st, ast.Expr) and isinstance(st.value, ast.Constant):
                        continue  # docstring
                    raise Skip("statement %s" % type(st).__name__)
                except Skip as e:
                    reasons.append(str(e))

        walk(f.body)
        if any("freeze_time" in d for d in decos):
            reasons.append("uses freeze_time / generated dtstart")
            got = []
        for i, g in enumerate(got):
            sk = g["skel"]
            name = qual + ("" if len(got) == 1 else " #%d" % (i + 1))
            cm = list(sk["comments"])
            if g["extra"]:
                cm.append(g["extra"])
            if g["error"]:
                cm.append("source expects ValueError")
                if "BadRRule" in f.name or "BadComboRRule" in f.name:
                    cm.append("dateutil-specific: it raises when the BYxxx/INTERVAL combination can never produce an instance; RFC 5545 does not define this as an error (an RFC implementation may simply yield nothing)")
            if xfail:
                cm.append("marked xfail upstream")
            cm.append("source line %d" % g["line"])
            self.cases.append(dict(name=name, skel=sk, expected=g["expected"], between=g["between"],
                                   limit=g["limit"], error=g["error"], comment="; ".join(cm)))
        self.func_status.append(dict(name=qual, extracted=len(got), skipped_reasons=reasons))


def categorize(reason):
    r = reason
    if r.startswith("str() round-trip"):
        return "str()/rrulestr round-trip tests (_rrulestr_reverse_test; no expected instance list)"
    if r.startswith("non-instance-list") or r.startswith("other assertion") or r.startswith("other API"):
        return "assert something other than an instance list (count(), before(), contains, isinstance, str/repr, replace, ...)"
    if r.startswith("__getitem__"):
        return "__getitem__ index / non-prefix slice API"
    if "freeze_time" in r or "no dtstart" in r:
        return "no explicit dtstart (dateutil uses now(); freeze_time tests)"
    if "python2" in r or "long()" in r:
        return "python2-only code (long())"
    if "rruleset members have different dtstart" in r or "without rrule" in r:
        return "rruleset whose member rules have different dtstarts or no rrule (not representable with one DTSTART)"
    if "tz" in r and ("unsupported" in r or "zone" in r):
        return "non-IANA tzinfo (tzstr/tzoffset/tzids mapping) or mixed zones"
    if "rrulestr kwargs" in r:
        return "rrulestr options not representable (ignoretz/tzids/tzinfos)"
    if "microseconds" in r:
        return "sub-second (microsecond) dtstart"
    if "warns" in r:
        return "warning-only test (COUNT+UNTIL deprecation)"
    if "for-loop" in r:
        return "loops / count() cache tests"
    if "multiple DTSTART" in r or "unrepresentable date value" in r:
        return "DTSTART/EXDATE text not representable as a single basic-format value"
    if "assertRaises without" in r or "ImportFrom" in r or "assertNotEqual" in r:
        return "weekday-object helper tests (not recurrence expansion)"
    if "TzInfoError" in r:
        return "rrulestr options not representable (ignoretz/tzids/tzinfos)"
    if "unsupported call str" in r:
        return "no explicit dtstart (dateutil uses now(); freeze_time tests)"
    return "other: " + r


def main():
    path, out, commit, report = sys.argv[1:5]
    tree = ast.parse(open(path, encoding="utf-8").read(), filename=path)
    ex = Extractor()
    ex.run(tree)
    cases = []
    for i, c in enumerate(ex.cases):
        sk = c["skel"]
        cases.append(vc.make_case(
            "dateutil-%04d" % (i + 1), sk["dtstart"], sk["rrule"], c["expected"], sk["include_dtstart"],
            name=c["name"], tzid=sk.get("tzid"), exrule=sk["exrule"], rdate=sk["rdate"], exdate=sk["exdate"],
            between=c["between"], limit=c["limit"], error=c["error"], extensions=sk["ext"], comment=c["comment"]))
    vc.write(out, "dateutil", "https://github.com/dateutil/dateutil", commit,
             "Apache-2.0 AND BSD-3-Clause", "tests/test_rrule.py", SEM, cases)
    total = len(ex.func_status)
    none = [f for f in ex.func_status if f["extracted"] == 0]
    partial = [f for f in ex.func_status if f["extracted"] and f["skipped_reasons"]]
    cat = Counter()
    for f in none:
        if f["name"].startswith("WeekdayTest."):
            cat["weekday-object helper tests (not recurrence expansion)"] += 1
            continue
        if f["name"].startswith("RRuleSetTest.") and "Count" in f["name"]:
            cat["count() / cache tests (no instance list)"] += 1
            continue
        cat[categorize(f["skipped_reasons"][0]) if f["skipped_reasons"] else "no assertions found"] += 1
    pcat = Counter()
    for f in partial:
        for r in f["skipped_reasons"]:
            pcat[categorize(r)] += 1
    rep = dict(test_functions=total, with_vectors=total - len(none), not_extracted=len(none),
               not_extracted_by_category=cat.most_common(), partially_extracted=len(partial),
               partial_skipped_assertions_by_category=pcat.most_common(),
               not_extracted_list=[(f["name"], f["skipped_reasons"][:2]) for f in none],
               partial_list=[(f["name"], f["skipped_reasons"]) for f in partial])
    json.dump(rep, open(report, "w"), indent=1)
    print(json.dumps({k: rep[k] for k in ("test_functions", "with_vectors", "not_extracted", "not_extracted_by_category", "partially_extracted", "partial_skipped_assertions_by_category")}, indent=1))


if __name__ == "__main__":
    main()
